@extends('layouts.admin') @section('title','Pedidos y despachos') @section('content')<form class="panel" method="GET"><div class="form-grid"><p><label>Pago</label><select name="status"><option value="">Todos</option>@foreach(['pending'=>'Pendiente de pago','paid'=>'Pagado','failed'=>'Fallido'] as $key=>$label)<option value="{{ $key }}" @selected(request('status')===$key)>{{ $label }}</option>@endforeach</select></p><p><label>Despacho</label><select name="fulfillment"><option value="">Todos</option>@foreach(['pending'=>'Pendiente','preparing'=>'En preparación','shipped'=>'Enviado','delivered'=>'Entregado','cancelled'=>'Cancelado'] as $key=>$label)<option value="{{ $key }}" @selected(request('fulfillment')===$key)>{{ $label }}</option>@endforeach</select></p></div><button>Filtrar</button></form><section class="panel"><table class="table"><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Despacho</th><th>Fecha</th></tr>@foreach($orders as $order)<tr><td><a href="{{ route('admin.orders.show',$order) }}"><b>{{ $order->provider_reference }}</b></a></td><td>{{ $order->user?->name ?? 'Cliente eliminado' }}</td><td>${{ number_format($order->total,0,',','.') }}</td><td><span class="tag">{{ $order->payment_status }}</span></td><td><span class="tag">{{ $order->fulfillment_status }}</span></td><td>{{ $order->created_at->format('d/m/Y H:i') }}</td></tr>@endforeach</table>{{ $orders->links() }}</section>@endsection
